import json
d=json.load(open('dailylife.json'))
base=len(d['refs'])
adds=[{'t':'Moreno García, Juan Carlos (2012). Households. UCLA Encyclopedia of Egyptology. eScholarship.','u':'https://escholarship.org/uc/item/2bn8c9gz'},
{'t':'Toivari-Viitala, Jaana (2013). Marriage and Divorce. UCLA Encyclopedia of Egyptology. eScholarship.','u':'https://escholarship.org/uc/item/68f6w5gw'},
{'t':'Emerit, Sibylle (2013). Music and Musicians. UCLA Encyclopedia of Egyptology. eScholarship.','u':'https://escholarship.org/uc/item/6x587846'}]
have={r['u'] for r in d['refs']}
for a in adds:
    if a['u'] not in have: d['refs'].append(a)
idx={r['u']:i+1 for i,r in enumerate(d['refs'])}
H_,M_,U_=idx[adds[0]['u']],idx[adds[1]['u']],idx[adds[2]['u']]
V=lambda p,c:{'badge':'v','p':p,'cite':list(c)}
D=lambda p,c:{'badge':'d','p':p,'cite':list(c)}
N=lambda p,c:{'p':p,'cite':list(c)}
H=lambda h:{'h':h}
new=[
{'title':'البيت والعائلة','banner':None,'blocks':[
 H('الأسرة وحدة المجتمع'),
 V('يقول خوان كارلوس مورينو غارسيا (UCLA، 2012) إن الأسرة (البيت) كانت الوحدة الأساسية للتنظيم الاجتماعي في مصر القديمة، وإن تكوينها كان يختلف بحسب الاعتبار الإداري أو الاجتماعي: فالسجلات الإدارية تركز على الأسرة النووية، بينما تؤكد المصادر الخاصة أهمية الأسرة الممتدة (Moreno García 2012).',(H_,)),
 V('ويضيف أن البيت لم يضم أصحاب القرابة فحسب، بل أتباعًا وعملاء وتابعين و«أصدقاء»، وربما بلغ عدد أفراده مئات الأشخاص، وأن مصادر ثروته جمعت أملاكًا موروثة ومؤسسية، وأن الديون وقلة الموارد والخلاف على الميراث كانت تهدد البيت بالتفكك (Moreno García 2012).',(H_,)),
 D('محل خلاف: يذكر مورينو غارسيا أن كلمة «بر» (بيت) تظهر في الوثائق الإدارية وحدةً أساسية، وأن لِهنر (Lehner) يرى أن الدولة المصرية كلها تُفهم على أنها «بيت من البيوت» لا دولة شديدة المركزية. ويقول في المقابل إن صورة الأسرة الإدارية تختلف كثيرًا عن صورتها الاجتماعية، لأن التعدادات تسجل الأسر النووية لأغراض الضرائب ولا تعكس البنى الاجتماعية. فلا يُعلن في هذا الموضع ترجيح نهائي بين الصورتين، وإنما يحذّر من الاعتماد على الوثائق الإدارية وحدها (Moreno García 2012).',(H_,)),
 H('ما لم يُتحقق منه'),
 N('لم يُتحقق منه: تصاميم البيوت وأثاثها وتفاصيل الحياة داخلها (غرف النوم والمطابخ والإضاءة). لم نجد في الصفحات التي راجعناها ما يوثقها بصفحة. قرية العمال في دير المدينة قسم قائم بذاته في صفحة العمارة والفنون.',(H_,))]},
{'title':'الزواج والطلاق','banner':None,'blocks':[
 H('الزواج بوصفه عقدًا'),
 V('تقول جانا تويفاري فيتالا (UCLA، 2013) إن الزواج كان بنية اجتماعية مركزية في الثقافة المصرية القديمة، يوفر الإطار الشرعي لإنجاب الأبناء الذين يرثون ويؤدون الطقوس الجنائزية لآبائهم. وتضيف أنه يمكن تعريفه بأنه عقد في ضوء نصوص الدولة الحديثة (1548-1086 ق.م) (Toivari-Viitala 2013).',(M_,)),
 V('وتذكر أن للزوج والزوجة والأبناء حقوقًا متساوية في الممتلكات الزوجية المشتركة بنسبة الثلث لكل منهم، وأنه كان يجوز لكل من الزوجين أن يملك ممتلكات خاصة. وكان الزواج يسبقه اختيار الشريك ثم تبادل الهدايا والممتلكات، وكان متوقعًا من الطرفين الامتناع عن العلاقات خارج الزواج، ويجوز للرجل أن تكون له أكثر من زوجة (Toivari-Viitala 2013).',(M_,)),
 N('وتنبه إلى أن العادات المحلية والمكانة الاجتماعية لا بد أنها غيّرت تفاصيل الزواج الفعلي، فزواج الملك يختلف عن زواج فلاح فقير، وأن الممارسات تغيرت بتغير الأزمنة (Toivari-Viitala 2013). ولهذا لا نعمم ما ورد على كل العصور.',(M_,)),
 H('ما لم يُتحقق منه'),
 N('لم يُتحقق منه: مراسم الزفاف وأعراسه، وعقود الزواج بنصوصها، وأسباب الطلاق وإجراءاته، وأعمار الزواج. تحتاج مراجع بصفحاتها ولم نضفها بعد.',(M_,))]},
{'title':'الموسيقى والموسيقيون','banner':None,'blocks':[
 H('مصادرنا عن الموسيقى'),
 V('تقول سيبيل إميريت (UCLA، 2013) إن مصادر الموسيقى المصرية القديمة وثائق تصويرية وأثرية ونصية من مواضع مختلفة تغطي التاريخ كله من عصر ما قبل الأسرات (نحو 3100 ق.م) إلى القرن الرابع الميلادي. وأهم المعلومات من مناظر جدران المقابر الخاصة والمعابد، ومن مناظر على التوابيت والبرديات والشقافات وعلى أدوات كالملاعق والأطباق، إضافة إلى التماثيل والتماثيل الصغيرة ونقوش بالهيروغليفية والهيراطيقية والديموطيقية واليونانية (Emerit 2013).',(U_,)),
 V('وتقول إن الموسيقى كان لها دور جوهري في كل العصور وأهمية بالغة في الطقوس والأعياد، وإنها كانت عامة وخاصة، دينية ودنيوية، يؤديها رجال ونساء محترفون أو هواة. وفي الدولة الحديثة تزخر النصوص بما يسمى «أغنية العازف» و«أغاني الحب» ونصوص طقسية كانت تُنشَد وترافقها آلات (Emerit 2013).',(U_,)),
 D('محل صعوبة: تقول إميريت إن ترجمة أسماء الآلات وألقاب الموسيقيين وألفاظ الأداء ما زالت صعبة، لأن اللفظ الواحد قد يحمل معاني عدة، والآلة الواحدة قد يكون لها أسماء عدة، وإن أغلب الآلات المكتشفة لا يُعرف مصدرها لأنها دخلت المتاحف قبل أن يوثَّق موضع العثور عليها (Emerit 2013). لذلك لا نجزم هنا بأسماء الآلات.',(U_,)),
 H('ما لم يُتحقق منه'),
 N('لم يُتحقق منه: أنواع الآلات بأسمائها العربية، وعدد الأوتار وطرق العزف، وألحان أو سلالم موسيقية. لا نكتب شيئًا منها قبل مرجع بصفحته.',(U_,))]}]
titles={s['title'] for s in d['sections']}
for s in new:
    if s['title'] not in titles: d['sections'].append(s)
json.dump(d,open('dailylife.json','w'),ensure_ascii=False,indent=1)
print(len(d['sections']),H_,M_,U_)
